<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { Clock3, CircleCheck, CircleX, UsersRound, Search, Eye, Check, X, RefreshCw, ChevronLeft, ChevronRight, ShieldCheck } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useAdminModerationStore } from '~/stores/api/adminModeration';
import { canAccessPage } from '~/utils/roles';

definePageMeta({ layout: 'default' });
const auth = useAuthStore(); const store = useAdminModerationStore();
const ready = ref(false); const tutors = ref([]); const detailOpen = ref(false); const rejectTarget = ref(null);
const reason = ref(''); const actionError = ref(''); const notice = ref('');
let searchTimer;
const input = 'min-w-0 w-full rounded-2xl border border-outline-variant bg-surface-container-low px-3 py-2.5 font-body-sm text-body-sm text-on-surface outline-none focus:border-primary-container';
const cards = computed(() => [
  { label:'Menunggu Review',value:store.summary.pending_review,icon:Clock3,tone:'bg-soft-orange text-on-secondary-container' },
  { label:'Approved Hari Ini',value:store.summary.approved_today,icon:CircleCheck,tone:'bg-success-soft text-success-emerald' },
  { label:'Rejected',value:store.summary.rejected,icon:CircleX,tone:'bg-danger-soft text-danger-rose' },
  { label:'Total Submission Tutor',value:store.summary.total_tutor_submission,icon:UsersRound,tone:'bg-pale-blue text-primary-container' },
]);
const subtests = ['PU','PPU','PBM','PK','LBI','LBE','PM'];
const diff = { easy:'Mudah',medium:'Sedang',hard:'Sulit' };
const levelLabel = item => ({ 1:'Fundamental', 2:'Intermediate', 3:'Advanced', 4:'Mastery' })[item.difficulty_level] || diff[item.difficulty] || '—';
const statusLabel = { review:'Menunggu Review',active:'Aktif',rejected:'Ditolak' };
function date(value) { return value ? new Date(value).toLocaleString('id-ID', { dateStyle:'medium', timeStyle:'short' }) : '—'; }
function roleName(item) { return Number(item?.role)===1 ? 'Admin' : 'Tutor'; }
function creatorName(item) { return item?.role===1 ? item.nama || 'Admin MatrIQ' : item?.nama || 'Tutor'; }
async function refresh() { await Promise.all([store.fetchSummary().catch(() => {}),store.fetchModerationQueue()]); }
function applyFilters() { store.pagination.page=1; store.fetchModerationQueue(); }
watch(() => store.filters.search, () => { clearTimeout(searchTimer); searchTimer=setTimeout(applyFilters,350); });
watch(() => [store.filters.status,store.filters.subtest,store.filters.difficulty,store.filters.tutor_id,store.filters.date_from,store.filters.date_to,store.filters.sort],applyFilters);
onBeforeUnmount(() => clearTimeout(searchTimer));
async function loadTutors() { try { const response=await store.request('/admin/users',{query:{role:3,limit:100}}); tutors.value=response.data||[]; } catch { tutors.value=[]; } }
async function openDetail(id) { detailOpen.value=true; await store.fetchModerationDetail(id); }
function openReject(item) { rejectTarget.value=item; reason.value=''; actionError.value=''; }
async function approve(item) {
  actionError.value=''; notice.value='';
  try { const response=await store.approveQuestion(item.id); notice.value=response.message; detailOpen.value=false; await store.fetchModerationQueue(); }
  catch (error) { actionError.value=error?.data?.message||'Gagal menyetujui soal.'; }
}
async function reject() {
  if (!reason.value.trim()) { actionError.value='Alasan penolakan wajib diisi.'; return; }
  actionError.value=''; notice.value='';
  try { const response=await store.rejectQuestion(rejectTarget.value.id,reason.value.trim()); notice.value=response.message; rejectTarget.value=null; detailOpen.value=false; await store.fetchModerationQueue(); }
  catch (error) { actionError.value=error?.data?.message||'Gagal menolak soal.'; }
}
onMounted(async () => {
  auth.initializeAuth(); if (!auth.token) return navigateTo('/login');
  const user=await auth.fetchCurrentUser();
  if (Number(user?.role)!==1 || !canAccessPage(user?.role,'content-moderation')) return navigateTo('/dashboard');
  ready.value=true; await Promise.all([refresh(),loadTutors()]);
});
</script>
<template>
  <div class="mx-auto w-full max-w-[1500px] min-w-0 px-4 py-5 sm:px-6 sm:py-7 lg:px-8">
    <template v-if="ready && Number(auth.user?.role)===1">
      <header class="mb-5"><h1 class="font-headline-md text-headline-md text-on-surface">Content Moderation</h1><p class="mt-1 font-body-sm text-body-sm text-on-surface-variant">Review soal yang dikirim Tutor sebelum dipublikasikan ke Bank Soal MatrIQ.</p></header>
      <p v-if="notice" role="status" class="mb-4 rounded-2xl bg-success-soft p-3 text-success-emerald">{{ notice }}</p><p v-if="actionError && !rejectTarget" role="alert" class="mb-4 rounded-2xl bg-danger-soft p-3 text-danger-rose">{{ actionError }}</p>
      <section class="mb-5 grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4" aria-label="Ringkasan moderasi"><article v-for="card in cards" :key="card.label" class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-5"><div class="mb-3 flex h-11 w-11 items-center justify-center rounded-2xl" :class="card.tone"><component :is="card.icon" class="h-[22px] w-[22px]" /></div><p class="font-caption text-caption text-outline">{{ card.label }}</p><div v-if="card.value==null" class="mt-2 h-8 w-16 animate-pulse rounded-lg bg-surface-container" /><p v-else class="mt-1 font-headline-md text-headline-md text-on-surface">{{ card.value }}</p></article></section>
      <section class="mb-5 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-5" aria-label="Filter moderasi"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label class="relative"><span class="sr-only">Cari soal atau tutor</span><Search class="pointer-events-none absolute left-3 top-3 h-4 w-4 text-outline" /><input v-model="store.filters.search" type="search" placeholder="Cari soal atau nama tutor..." :class="input" class="pl-9" /></label><label><span class="sr-only">Status</span><select v-model="store.filters.status" :class="input"><option value="review">Menunggu Review</option><option value="active">Approved</option><option value="rejected">Rejected</option></select></label><label><span class="sr-only">Subtes</span><select v-model="store.filters.subtest" :class="input"><option value="">Semua Subtes</option><option v-for="item in subtests" :key="item" :value="item">{{ item }}</option></select></label><label><span class="sr-only">Kesulitan</span><select v-model="store.filters.difficulty" :class="input"><option value="">Semua Kesulitan</option><option value="1">Fundamental</option><option value="2">Intermediate</option><option value="3">Advanced</option><option value="4">Mastery</option></select></label><label><span class="sr-only">Tutor</span><select v-model="store.filters.tutor_id" :class="input"><option value="">Semua Tutor</option><option v-for="tutor in tutors" :key="tutor.user_id" :value="tutor.user_id">{{ tutor.nama }}</option></select></label><label><span class="sr-only">Dari tanggal</span><input v-model="store.filters.date_from" type="date" :class="input" /></label><label><span class="sr-only">Sampai tanggal</span><input v-model="store.filters.date_to" type="date" :class="input" /></label><label><span class="sr-only">Urutkan</span><select v-model="store.filters.sort" :class="input"><option value="oldest">Terlama dahulu</option><option value="newest">Terbaru dahulu</option></select></label></div></section>
      <section class="min-w-0 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-title-md text-title-md text-on-surface">{{ store.filters.status==='review' ? 'Antrean Review' : 'Riwayat Moderasi' }}</h2><p class="mt-1 font-caption text-caption text-outline">{{ store.pagination.total }} soal Tutor</p></div><button class="inline-flex items-center gap-2 rounded-xl border border-soft-blue px-3 py-2 text-on-surface-variant hover:bg-surface-container-low" @click="refresh"><RefreshCw class="h-4 w-4" />Muat Ulang</button></div>
        <div v-if="store.error" role="alert" class="rounded-2xl bg-danger-soft p-4 text-danger-rose">{{ store.error }} <button class="ml-2 underline" @click="refresh">Coba Lagi</button></div><div v-else-if="store.isLoading" class="space-y-3"><div v-for="i in 5" :key="i" class="h-32 animate-pulse rounded-2xl bg-surface-container" /></div><div v-else-if="!store.items.length" class="py-12 text-center"><CircleCheck class="mx-auto mb-3 h-10 w-10 text-success-emerald" /><h3 class="font-title-md text-title-md">{{ store.filters.status==='review' ? 'Semua beres 🎉' : 'Belum ada soal' }}</h3><p class="mt-1 text-on-surface-variant">{{ store.filters.status==='review' ? 'Tidak ada soal Tutor yang menunggu review saat ini.' : 'Tidak ada soal untuk filter ini.' }}</p></div>
        <div v-else class="space-y-3"><article v-for="item in store.items" :key="item.id" class="min-w-0 rounded-2xl border border-soft-blue p-4 sm:p-5"><div class="flex flex-wrap items-center gap-2 text-xs"><span class="rounded-full bg-pale-blue px-2.5 py-1 text-primary-container">{{ item.subtest }}</span><span class="rounded-full bg-surface-container px-2.5 py-1 text-outline">{{ item.category }}</span><span v-if="item.material_title" class="rounded-full bg-surface-container px-2.5 py-1 text-outline">{{ item.material_title }}</span><span class="rounded-full bg-surface-container px-2.5 py-1 text-outline">{{ levelLabel(item) }}</span><span class="ml-auto rounded-full px-2.5 py-1" :class="item.status==='review'?'bg-soft-orange text-on-secondary-container':item.status==='active'?'bg-success-soft text-success-emerald':'bg-danger-soft text-danger-rose'">{{ statusLabel[item.status] }}</span></div><p class="mt-3 line-clamp-3 font-label-md text-label-md text-on-surface">{{ item.question }}</p><div class="mt-4 flex flex-wrap items-end justify-between gap-3"><div class="flex items-center gap-2"><img v-if="item.creator?.foto_profile" :src="item.creator.foto_profile" alt="" class="h-9 w-9 rounded-full object-cover" /><span v-else class="flex h-9 w-9 items-center justify-center rounded-full bg-pale-blue text-primary-container">{{ item.creator?.nama?.slice(0,1) || 'T' }}</span><span><span class="block text-xs text-outline">Dibuat oleh</span><strong class="block text-sm">{{ creatorName(item.creator) }} <small class="font-normal text-outline">· {{ roleName(item.creator) }}</small></strong><small class="block text-outline">Diajukan {{ date(item.submitted_at || item.created_at) }}</small></span></div><div class="flex flex-wrap gap-2"><button class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm" @click="openDetail(item.id)"><Eye class="h-4 w-4" />Detail</button><template v-if="item.status==='review'"><button :disabled="store.isReviewing" class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm text-danger-rose disabled:opacity-50" @click="openReject(item)"><X class="h-4 w-4" />Tolak</button><button :disabled="store.isReviewing" class="inline-flex items-center gap-1 rounded-xl bg-primary-container px-3 py-2 text-sm text-white disabled:opacity-50" @click="approve(item)"><Check class="h-4 w-4" />Setujui</button></template></div></div><p v-if="item.status==='rejected' && item.rejection_reason" class="mt-3 rounded-xl bg-danger-soft p-3 text-sm text-danger-rose">Alasan: {{ item.rejection_reason }}</p></article></div>
        <div class="mt-5 flex items-center justify-end gap-3 text-sm"><span>Halaman {{ store.pagination.page }} / {{ store.pagination.total_pages }}</span><button :disabled="store.pagination.page<=1" class="rounded-xl border border-soft-blue p-2 disabled:opacity-40" aria-label="Halaman sebelumnya" @click="store.pagination.page--; store.fetchModerationQueue()"><ChevronLeft class="h-4 w-4" /></button><button :disabled="store.pagination.page>=store.pagination.total_pages" class="rounded-xl border border-soft-blue p-2 disabled:opacity-40" aria-label="Halaman berikutnya" @click="store.pagination.page++; store.fetchModerationQueue()"><ChevronRight class="h-4 w-4" /></button></div>
      </section>
      <div v-if="detailOpen" class="fixed inset-0 z-50 flex justify-end bg-black/40" @click.self="detailOpen=false"><div role="dialog" aria-modal="true" aria-label="Detail review soal" class="h-full w-full max-w-2xl overflow-y-auto bg-surface-white p-5 shadow-2xl sm:p-7"><div class="mb-5 flex justify-between gap-3"><h2 class="font-title-md text-title-md">Detail Review Soal</h2><button aria-label="Tutup detail" @click="detailOpen=false"><X class="h-5 w-5" /></button></div><p v-if="store.isLoadingDetail">Memuat detail...</p><p v-else-if="store.detailError" role="alert">{{ store.detailError }}</p><template v-else-if="store.selectedItem"><div class="mb-4 flex flex-wrap gap-2 text-xs"><span class="rounded-full bg-pale-blue px-2.5 py-1 text-primary-container">{{ store.selectedItem.subtest }}</span><span class="rounded-full bg-surface-container px-2.5 py-1">{{ store.selectedItem.category }}</span><span v-if="store.selectedItem.material" class="rounded-full bg-surface-container px-2.5 py-1">{{ store.selectedItem.material.title }}</span><span class="rounded-full bg-surface-container px-2.5 py-1">{{ levelLabel(store.selectedItem) }}</span><span class="rounded-full bg-soft-orange px-2.5 py-1">{{ statusLabel[store.selectedItem.status] }}</span></div><p class="mb-5 whitespace-pre-wrap font-label-md text-label-md text-on-surface">{{ store.selectedItem.question }}</p><h3 class="mb-2 font-label-sm text-label-sm">Pilihan Jawaban</h3><div class="space-y-2"><div v-for="option in store.selectedItem.options || []" :key="option.key" class="rounded-2xl border p-3" :class="option.key===store.selectedItem.correct_answer?'border-success-emerald bg-success-soft':'border-soft-blue'"><strong class="mr-2">{{ option.key }}</strong>{{ option.text }}<span v-if="option.key===store.selectedItem.correct_answer" class="ml-2 text-xs text-success-emerald">✓ Jawaban Benar</span></div></div><h3 class="mb-2 mt-5 font-label-sm text-label-sm">Pembahasan</h3><p class="whitespace-pre-wrap rounded-2xl bg-surface-container-low p-4 text-sm">{{ store.selectedItem.explanation }}</p><div class="mt-5 border-t border-soft-blue pt-4 text-sm text-on-surface-variant"><p>Dibuat oleh {{ creatorName(store.selectedItem.created_by) }} · {{ roleName(store.selectedItem.created_by) }}</p><p>Diajukan {{ date(store.selectedItem.submitted_at || store.selectedItem.created_at) }}</p><p v-if="store.selectedItem.reviewer">Direview oleh {{ store.selectedItem.reviewer.nama }} pada {{ date(store.selectedItem.reviewed_at) }}</p><p v-if="store.selectedItem.rejection_reason" class="mt-2 rounded-xl bg-danger-soft p-3 text-danger-rose">Alasan penolakan: {{ store.selectedItem.rejection_reason }}</p></div><div v-if="store.selectedItem.status==='review'" class="mt-5 flex justify-end gap-2"><button class="rounded-xl border border-soft-blue px-4 py-2 text-danger-rose" @click="openReject(store.selectedItem)">Tolak</button><button class="rounded-xl bg-primary-container px-4 py-2 text-white" @click="approve(store.selectedItem)">Setujui</button></div></template></div></div>
      <div v-if="rejectTarget" class="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4" @click.self="rejectTarget=null"><form role="dialog" aria-modal="true" aria-label="Tolak soal" class="w-full max-w-lg rounded-3xl bg-surface-white p-5 shadow-2xl" @submit.prevent="reject"><div class="mb-4 flex justify-between"><h2 class="font-title-md text-title-md">Tolak Soal</h2><button type="button" aria-label="Tutup dialog" @click="rejectTarget=null"><X class="h-5 w-5" /></button></div><label class="block font-label-sm text-label-sm">Alasan Penolakan<textarea v-model="reason" required minlength="5" maxlength="2000" rows="4" placeholder="Contoh: pembahasan belum lengkap atau jawaban benar tidak sesuai." :class="input" class="mt-2" /></label><p v-if="actionError" role="alert" class="mt-3 text-sm text-danger-rose">{{ actionError }}</p><div class="mt-5 flex justify-end gap-2"><button type="button" class="rounded-xl border border-soft-blue px-4 py-2" @click="rejectTarget=null">Batal</button><button type="submit" :disabled="store.isReviewing" class="rounded-xl bg-danger-rose px-4 py-2 text-white disabled:opacity-50">Tolak Soal</button></div></form></div>
    </template><div v-else class="h-40 animate-pulse rounded-3xl bg-surface-container" aria-label="Memuat moderasi" />
  </div>
</template>
